def gg(l, r, need, alphaSize):
    m = l + (r - l) // 2
    if need < m:
        return gg(l, m - 1, need, alphaSize - 1)
    elif need > m:
        return gg(m + 1, r, need, alphaSize - 1)
    return alphaSize

